package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.apache.commons.lang3.text.translate.CharSequenceTranslator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class CharSequenceTranslator_with_TriageGen2Test {

    /**
     * Mock implementation of CharSequenceTranslator to test aggregation logic.
     */
    private static class MockTranslator extends CharSequenceTranslator {
        private final String replacement;

        MockTranslator(String replacement) {
            this.replacement = replacement;
        }

        @Override
        public int translate(CharSequence input, int index, StringWriter out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }

        @Override
        public int translate(CharSequence input, int index, java.io.Writer out) throws IOException {
            out.write(replacement);
            return replacement.length();
        }
    }

    @Test
    public void testWith_SingleTranslator() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("base");
        CharSequenceTranslator extra = new MockTranslator("extra");

        // Act
        CharSequenceTranslator result = base.with(extra);

        // Assert
        assertNotNull(result);
        StringWriter sw = new StringWriter();
        // AggregateTranslator should call base then extra
        // Note: The implementation puts 'this' at index 0 and others at 1..N
        result.translate("test", sw);
        assertEquals("baseextra", sw.toString());
    }

    @Test
    public void testWith_MultipleTranslators() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("1");
        CharSequenceTranslator t1 = new MockTranslator("2");
        CharSequenceTranslator t2 = new MockTranslator("3");
        CharSequenceTranslator t3 = new MockTranslator("4");

        // Act
        CharSequenceTranslator result = base.with(t1, t2, t3);

        // Assert
        assertNotNull(result);
        StringWriter sw = new StringWriter();
        result.translate("test", sw);
        assertEquals("1234", sw.toString());
    }

    @Test
    public void testWith_EmptyArray() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("base");

        // Act
        // Passing nothing to varargs results in an empty array
        CharSequenceTranslator result = base.with();

        // Assert
        assertNotNull(result);
        StringWriter sw = new StringWriter();
        result.translate("test", sw);
        assertEquals("base", sw.toString());
    }

    @Test
    public void testWith_NullArgument() throws IOException {
        // Arrange
        CharSequenceTranslator base = new MockTranslator("base");

        // Act & Assert
        // Passing null to a varargs parameter results in a NullPointerException 
        // during the array length access or System.arraycopy if not handled.
        try {
            base.with(null);
        } catch (NullPointerException e) {
            // Expected behavior for the provided implementation
        }
    }
}
